#!/bin/bash
# 25_music_pages_wire.sh
# 四页面 UI 重构最后一步：注入歌单/设置/搜索三页 + 统一接入导航并接上真实数据
# - RankScreen 已由 24_music_rank_screen.sh 注入
# - 本脚本：写 PlaylistScreen/SettingsScreen/SearchScreen 三个文件，
#   然后给 MusicHomeActivity.kt 打导航接线补丁（数据壳保留、新 UI 注入）
set -e
cd "$(dirname "$0")/../.." 2>/dev/null || true
BASE="avbox"
MUSIC_DIR="$BASE/app/src/main/java/com/github/tvbox/osc/ui/music"

write_page() {
  local dir="$1" file="$2" mark="$3" b64="$4"
  mkdir -p "$MUSIC_DIR/$dir"
  if [ -f "$MUSIC_DIR/$dir/$file" ] && grep -q "$mark" "$MUSIC_DIR/$dir/$file" 2>/dev/null; then
    echo "跳过（$file 已写入）"
  else
    echo "$b64" | base64 -d > "$MUSIC_DIR/$dir/$file"
    echo "已写入 $dir/$file"
  fi
}

write_page "playlist" "PlaylistScreen.kt" "方案 B：封面内缩悬浮" ""
write_page "settings" "SettingsScreen.kt" "细节4：设置项" ""
write_page "search" "SearchScreen.kt" "细节2：搜索框" ""

# ---- 导航接线补丁 ----
TARGET="$BASE/app/src/main/java/com/github/tvbox/osc/ui/activity/MusicHomeActivity.kt"
if [ ! -f "$TARGET" ]; then
  echo "FATAL: 未找到 $TARGET，导航接线无法应用，构建中止"
  exit 1
fi

python3 - "$TARGET" <<'PYEOF'
import re, sys

import sys
path = sys.argv[1]
src = open(path, encoding='utf-8').read()
MARK = '// NAV_WIRE_V1'
if MARK in src:
    print("已打过补丁，跳过"); sys.exit(0)

def func_span(src, sig):
    s = src.find(sig)
    assert s > 0, f"未找到 {sig}"
    m = re.search(r'\n(?:/\*\*[\s\S]*?\*/\n)?(?:@Composable\n)?(?:private )?fun \w+', src[s+20:])
    end = s + 20 + m.start() if m else len(src)
    body = src[s:end].rstrip()
    assert body.endswith('}'), f"{sig} 结尾不是 }}"
    return s, end

def replace_ui(src, sig, ui_anchor_re, new_ui):
    s, end = func_span(src, sig)
    m = re.search(ui_anchor_re, src[s:end])
    assert m, f"{sig} 未找到 UI 锚点"
    ui_start = s + m.start()
    new_src = src[:ui_start] + new_ui + '\n' + src[end:]
    return new_src

# ---- 1. 导入 ----
imports = (
    "\n// NAV_WIRE_V1: 新版四页面导入\n"
    "import com.github.tvbox.osc.ui.music.rank.RankScreen\n"
    "import com.github.tvbox.osc.ui.music.rank.RankSong\n"
    "import com.github.tvbox.osc.ui.music.playlist.PlaylistScreen\n"
    "import com.github.tvbox.osc.ui.music.playlist.Playlist as NewPlaylist\n"
    "import com.github.tvbox.osc.ui.music.search.SearchScreen\n"
    "import com.github.tvbox.osc.ui.music.settings.SettingsScreen\n"
    "import com.github.tvbox.osc.ui.music.settings.SettingGroup as NewSettingGroup\n"
    "import com.github.tvbox.osc.ui.music.settings.SettingItem as NewSettingItem\n"
)
last_imp = max(m.end() for m in re.finditer(r'^import .+$', src, re.M))
src = src[:last_imp] + imports + src[last_imp:]

# ---- 2. RankingTab -> RankScreen ----
rank_ui = """    // NAV_WIRE_V1: 排行榜新版 UI（RankScreen）；榜单/歌曲数据逻辑保持不动
    // selectedTab 状态由本层持有，切 Tab 回来不丢失
    RankScreen(
        songs = songs.map { RankSong(title = it.title, artist = it.artist, coverUrl = it.picUrl) },
        tabs = charts.map { it.name },
        selectedTab = selectedChart.name,
        onTabSelected = { name -> charts.find { it.name == name }?.let { selectedChart = it } },
        title = platformName,
        onSongClick = { song ->
            val idx = songs.indexOfFirst { it.title == song.title && it.artist == song.artist }
            if (idx >= 0) playSongs(context, songs, idx)
        },
        onPlayClick = { song ->
            val idx = songs.indexOfFirst { it.title == song.title && it.artist == song.artist }
            if (idx >= 0) playSongs(context, songs, idx)
        },
    )
}"""
src = replace_ui(src, 'fun RankingTab(',
    r"\n    Row\(modifier = Modifier\.fillMaxSize\(\)\) \{\n        // 左侧榜单列表", rank_ui)

# ---- 3. PlaylistBrowser -> PlaylistScreen ----
pl_ui = """    // NAV_WIRE_V1: 歌单新版 UI（PlaylistScreen）；分类/歌单数据逻辑保持不动
    PlaylistScreen(
        playlists = playlists.map {
            NewPlaylist(id = it.id, name = it.name, coverUrl = it.coverUrl, playCount = it.playCount)
        },
        categories = categories,
        selectedCategory = selectedCat,
        onCategorySelected = { selectedCat = it },
        platformSupported = platform in listOf("wy", "tx", "kg"),
        onLoadMore = { loadMorePlaylists() },
        onRefresh = { refreshPlaylists() },
        isRefreshing = isRefreshing,
        isLoadingMore = isLoadingMore,
        gridState = gridState,
        onPlaylistClick = { id, name -> onOpen(id, name) },
    )
}"""
src = replace_ui(src, 'private fun PlaylistBrowser(', r"\n    Column\(", pl_ui)

# ---- 4. SearchTabLanding -> SearchScreen ----
se_ui = """    // NAV_WIRE_V1: 搜索新版 UI（SearchScreen）；热词/关键词数据逻辑保持不动
    SearchScreen(
        keyword = keyword,
        onKeywordChange = { keyword = it },
        hotWords = hotWords,
        onHotWordClick = { kw -> if (!isSearching) { isSearching = true; goSearch(kw) } },
        onSearch = { kw -> if (!isSearching) { isSearching = true; goSearch(kw) } },
        isSearching = isSearching,
    )
}"""
src = replace_ui(src, 'fun SearchTabLanding(', r"\n    LazyColumn\(", se_ui)

# ---- 5. MusicSettingsList -> SettingsScreen ----
st_ui = """    // NAV_WIRE_V1: 设置新版 UI（SettingsScreen）；分组数据保持不动
    SettingsScreen(
        groups = groups.map { g ->
            NewSettingGroup(
                header = g.header,
                items = g.items.map { i ->
                    NewSettingItem(title = i.title, subtitle = i.subtitle, action = i.action)
                }
            )
        }
    )
}"""
src = replace_ui(src, 'fun MusicSettingsList(onComingSoon', r"\n    LazyColumn\(", st_ui)

# ---- 6. 底部导航选中色 -> primary（坑1） ----
src = src.replace(
    'color = if (selectedTab == tab) AccentBlue else TextGray,',
    'color = if (selectedTab == tab) MaterialTheme.colorScheme.primary else TextGray,')
src = src.replace(
    'color = if (selectedTab == tab) AccentBlue else TextGray\n',
    'color = if (selectedTab == tab) MaterialTheme.colorScheme.primary else TextGray\n')
src = src.replace(
    'selectedIconColor = AccentBlue,',
    'selectedIconColor = MaterialTheme.colorScheme.primary,')
src = src.replace(
    'indicatorColor = AccentBlue.copy(alpha = 0.15f)',
    'indicatorColor = MaterialTheme.colorScheme.primary.copy(alpha = 0.15f)')

# ---- 7. 分支注释 ----
src = src.replace('// 搜索落地页：搜索框 + 热搜榜 + 彩色分类卡',
                  '// 搜索：新版 SearchScreen（数据：SearchTabLanding 的热词/关键词逻辑）')
src = src.replace('// 排行榜：按平台加载榜单',
                  '// 排行：新版 RankScreen（数据：RankingTab 的榜单/歌曲逻辑）')
src = src.replace('// 歌单：真实歌单 API，点击进详情',
                  '// 歌单：新版 PlaylistScreen（数据：PlaylistTab/PlaylistBrowser 的歌单逻辑）')
src = src.replace('MusicSettingsList(onComingSoon = ::comingSoon)',
                  'MusicSettingsList(onComingSoon = ::comingSoon) // 新版 SettingsScreen')


# ---- 4b. SearchTabLanding 搜索状态（[25v2]） ----
if '[25v2]' not in src:
    kw_anchor = '    var keyword by remember { mutableStateOf("") }'
    if src.count(kw_anchor) != 1:
        print("失败：25v2 keyword 锚点计数异常", src.count(kw_anchor), file=sys.stderr); sys.exit(1)
    inject_txt = kw_anchor + '\n    var isSearching by remember { mutableStateOf(false) } // [25v2] 搜索提交反馈状态\n    LaunchedEffect(isSearching) {\n        if (isSearching) { delay(1200L); isSearching = false }\n    }'
    src = src.replace(kw_anchor, inject_txt, 1)
    if 'import kotlinx.coroutines.delay' not in src:
        imp_anchor = 'import kotlinx.coroutines.async'
        if src.count(imp_anchor) != 1:
            print("失败：25v2 import 锚点计数异常", src.count(imp_anchor), file=sys.stderr); sys.exit(1)
        src = src.replace(imp_anchor, imp_anchor + '\nimport kotlinx.coroutines.delay', 1)
    print("4b: SearchTabLanding 已加 isSearching 状态（[25v2]）")

open(path, 'w', encoding='utf-8').write(src)

# ---- 校验 ----
def balanced(s):
    d = 0
    for ch in s:
        if ch == '{': d += 1
        elif ch == '}': d -= 1
    return d
print("括号平衡:", balanced(src))
for sig in ['fun RankingTab(', 'private fun PlaylistBrowser(', 'fun SearchTabLanding(', 'fun MusicSettingsList(onComingSoon']:
    s, end = func_span(src, sig)
    print(sig, "OK, 长度", end - s)
print("NAV_WIRE_V1 标记数:", src.count(MARK))
print("RankScreen( 调用数:", src.count('RankScreen('))
print("PlaylistScreen( 调用数:", src.count('PlaylistScreen('))
print("SearchScreen( 调用数:", src.count('SearchScreen('))
print("SettingsScreen( 调用数:", src.count('SettingsScreen('))
print("残留 AccentBlue 在导航区:", src.count('selectedTab == tab) AccentBlue'))
PYEOF
echo "导航接线完成"

# === 25 glass1: 设置页毛玻璃（卡片半透明+高光边 / 底栏半透明+发丝线） ===
python3 << 'PYEOF25GLASS'
import sys, os
def load(p):
    while not os.path.exists(p) and os.getcwd() != "/":
        os.chdir("..")
    return open(p, encoding="utf-8").read()
def save(p, s):
    open(p, "w", encoding="utf-8").write(s)

SP = "avbox/app/src/main/java/com/github/tvbox/osc/ui/music/settings/SettingsScreen.kt"
s = load(SP)
if "[25glass1]" in s:
    print("跳过（25 glass1 设置卡片已应用）")
else:
    old = "import androidx.compose.foundation.BorderStroke"
    assert s.count(old) == 1, "SettingsScreen import 锚点"
    s = s.replace(old, old + "\nimport com.github.tvbox.osc.ui.activity.musicColors // [25glass1]", 1)
    old = "        color = MaterialTheme.colorScheme.surface,"
    assert s.count(old) == 1, "SettingsScreen 卡片底色锚点"
    s = s.replace(old, "        color = musicColors().card.copy(alpha = 0.75f), // [25glass1] 毛玻璃半透明卡", 1)
    old = "        border = BorderStroke(1.dp, Color.White.copy(alpha = 0.05f)),"
    assert s.count(old) == 1, "SettingsScreen 描边锚点"
    s = s.replace(old, "        border = BorderStroke(0.5.dp, Color.White.copy(alpha = 0.15f)), // [25glass1] 玻璃高光边", 1)
    save(SP, s)
    print("OK 25 glass1 设置卡片已玻璃化")

AP = "avbox/app/src/main/java/com/github/tvbox/osc/ui/activity/MusicHomeActivity.kt"
s = load(AP)
if "[25glass1]" in s:
    print("跳过（25 glass1 底栏已应用）")
else:
    # 注：MusicHomeActivity 用 material3.* 通配导入，HorizontalDivider 无需补 import
    old = "                NavigationBar(containerColor = BgDarker) {"
    assert s.count(old) == 1, "MusicHomeActivity 底栏锚点"
    new = ("                HorizontalDivider(thickness = 0.5.dp, color = musicColors().divider) // [25glass1] 底栏发丝线\n"
           "                NavigationBar(containerColor = musicColors().background.copy(alpha = 0.85f)) { // [25glass1] 玻璃底栏")
    s = s.replace(old, new, 1)
    save(AP, s)
    print("OK 25 glass1 底栏已玻璃化")
PYEOF25GLASS
echo "=== 25 glass1 完成 ==="

# === 25 glass2: 底栏极简化（纯文字、无图标、54dp 矮版） ===
python3 << 'PYEOF25GLASS2'
import sys, os
AP = "avbox/app/src/main/java/com/github/tvbox/osc/ui/activity/MusicHomeActivity.kt"
while not os.path.exists(AP) and os.getcwd() != "/":
    os.chdir("..")
s = open(AP, encoding="utf-8").read()
if "[25glass2]" in s:
    print("跳过（25 glass2 已应用）"); sys.exit(0)
start_anchor = "                NavigationBar(containerColor = musicColors().background.copy(alpha = 0.85f)) { // [25glass1] 玻璃底栏"
idx = s.find(start_anchor)
assert idx >= 0, "glass2 起点锚点未命中（glass1 未应用？）"
# 从起点按大括号配平找块尾（先见 depth>0 再认 depth==0）
i = idx + len(start_anchor)
depth = 1
seen = False
while i < len(s):
    ch = s[i]
    if ch == '{':
        depth += 1; seen = True
    elif ch == '}':
        depth -= 1
        if seen and depth == 0:
            break
    i += 1
assert seen and depth == 0, "glass2 块尾配平失败"
end = i + 1
new_block = """                Row( // [25glass2] 纯文字极简底栏：无图标、54dp 矮版
                    modifier = Modifier
                        .fillMaxWidth()
                        .height(54.dp)
                        .background(musicColors().background.copy(alpha = 0.85f)),
                    verticalAlignment = Alignment.CenterVertically,
                ) {
                    val tabDefs = listOf(
                        MusicTab.SEARCH to "搜索",
                        MusicTab.RANKING to "排行",
                        MusicTab.PLAYLIST to "歌单",
                        MusicTab.SETTINGS to "设置",
                        MusicTab.HOME to "首页",
                    )
                    tabDefs.forEach { (tab, label) ->
                        val isSel = selectedTab == tab
                        Box(
                            modifier = Modifier
                                .weight(1f)
                                .height(54.dp)
                                .clickable {
                                    if (tab == MusicTab.HOME) {
                                        onBackToAppHome()
                                    } else {
                                        selectedTab = tab
                                    }
                                },
                            contentAlignment = Alignment.Center,
                        ) {
                            Text(
                                text = label,
                                color = if (isSel) MaterialTheme.colorScheme.primary else TextGray,
                                fontWeight = if (isSel) FontWeight.Bold else FontWeight.Normal,
                                modifier = Modifier
                                    .clip(RoundedCornerShape(50))
                                    .background(if (isSel) MaterialTheme.colorScheme.primary.copy(alpha = 0.15f) else Color.Transparent)
                                    .padding(horizontal = 18.dp, vertical = 7.dp),
                            )
                        }
                    }
                }"""
s = s[:idx] + new_block + s[end:]
open(AP, "w", encoding="utf-8").write(s)
print("OK 25 glass2 底栏极简化完成")
PYEOF25GLASS2
echo "=== 25 glass2 完成 ==="
